import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as n,b as l,w as a,a as c,G as d,ag as h}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Group 2 · Inference & Interface","description":"One line from the prefill/decode stages to the user-visible interface — the physical structure of latency and cost, the serving cost levers, and a seven-topic guide covering the API contract, structured output, streaming, generative UI, and on-device access.","frontmatter":{"title":"Group 2 · Inference & Interface","description":"One line from the prefill/decode stages to the user-visible interface — the physical structure of latency and cost, the serving cost levers, and a seven-topic guide covering the API contract, structured output, streaming, generative UI, and on-device access.","domain":"tech","tags":["inference","interface","navigation"],"navOrder":19,"topicId":"integration","layer":"2","status":"canonical","nodeType":"problem","owner":"learn-ai","prerequisites":["model-lifecycle-bridge"],"next":["model-api","streaming","session-state"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/02-inference-interface/index.md","filePath":"tech/02-inference-interface/index.md","lastUpdated":1788326832000}'),u={name:"tech/02-inference-interface/index.md"};function p(m,e,f,g,b,v){const i=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=n('<h1 id="group-2-·-inference-interface" tabindex="-1">Group 2 · Inference &amp; Interface <a class="header-anchor" href="#group-2-·-inference-interface" aria-label="Permalink to &quot;Group 2 · Inference &amp; Interface&quot;">​</a></h1><blockquote><p><strong>Group</strong>: 2 · Inference &amp; Interface | <strong>Previous group exit</strong>: can explain how the model lifecycle shapes engineering decisions (the model is a replaceable capability with three interface properties: behavior, budget, capability boundary) | <strong>This group exit</strong>: can deliver a user-visible interaction that is attributable (latency decomposes into segments), observable (usage is visible), and cancellable <strong>Prerequisites</strong>: <a href="./../01-model-lifecycle/">Model Lifecycle (bridge)</a> | <strong>Next</strong>: <a href="./../03-context/session-memory.html">Session and State</a>, <a href="./../04-grounding/rag.html">Embeddings and Retrieval</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>This group answers one question: <strong>how do parameters become an online service and a contract?</strong> It is a single line that runs from the two-stage prefill/decode generation all the way to the user-visible interface — the first half explains where latency and cost come from (the TTFT and the bill you get are outputs of a pipeline, not magic), and the second half wires model capability into a product interaction (calling contract, output shape, presentation cadence, access point).</p><p>The first half used to be missing: an engineer who only learns &quot;how to call the API&quot; cannot explain why the first token is slow, why cached input is cheaper, or when to self-host serving. This group closes the gap with seven topics:</p><ul><li><strong>Serving side</strong> (what happens inside the model): <a href="./inference-fundamentals.html">Inference Fundamentals</a> decomposes the latency structure; <a href="./efficient-serving.html">Efficient Serving</a> decomposes the cost structure.</li><li><strong>Interface side</strong> (how you connect): <a href="./model-api.html">Model API Contract</a> stabilizes the call, <a href="./structured-output.html">Structured Output</a> stabilizes the shape, <a href="./streaming.html">Streaming</a> stabilizes the cadence, <a href="./ui.html">Generative UI</a> upgrades the presentation, <a href="./browser-edge.html">Browser and Edge Inference</a> changes the access point.</li></ul>',6)),(t(),l(h,null,{default:a(()=>[d(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BModel%20lifecycle%3Cbr%2F%3E(group%201%20bridge%20exit)%5D%20--%3E%20B%5Binference-fundamentals%3Cbr%2F%3Elatency%20structure%5D%0A%20%20%20%20B%20--%3E%20C%5Befficient-serving%3Cbr%2F%3Ecost%20mechanisms%5D%0A%20%20%20%20C%20--%3E%20D%5Bmodel-api%3Cbr%2F%3Ecalling%20contract%5D%0A%20%20%20%20D%20--%3E%20E%5Bstructured-output%3Cbr%2F%3Eoutput%20shape%5D%0A%20%20%20%20E%20--%3E%20F%5Bstreaming%3Cbr%2F%3Epresentation%20cadence%5D%0A%20%20%20%20F%20--%3E%20G%5Bui%20structured%20interface%5D%0A%20%20%20%20D%20--%3E%20H%5Bbrowser-edge%20on-device%20access%5D%0A%20%20%20%20G%20--%3E%20I%5BGroup%20exit%3A%20attributable%2C%20observable%2C%20cancellable%20interaction%5D%0A%20%20%20%20H%20--%3E%20I%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n(`<h3 id="when-to-enter-this-group-when-not-to" tabindex="-1">When to enter this group / when not to <a class="header-anchor" href="#when-to-enter-this-group-when-not-to" aria-label="Permalink to &quot;When to enter this group / when not to&quot;">​</a></h3><ul><li><strong>Enter</strong>: you are building a product on a model — read the first two pages to build the latency/cost mental model, then enter the interface side; or you already maintain an AI feature and need to attribute latency and cost.</li><li><strong>Do not enter</strong>: training and attention math — go back to the Learn LLM links in <a href="./../01-model-lifecycle/">Model Lifecycle (bridge)</a>; answers lack private facts — go to <a href="./../04-grounding/rag.html">Embeddings and Retrieval</a>; the system must take actions — go to <a href="./../05-action/tool-calling.html">Tool Calling Contract</a>.</li></ul><h3 id="symptom-→-topic-navigation" tabindex="-1">Symptom → topic navigation <a class="header-anchor" href="#symptom-→-topic-navigation" aria-label="Permalink to &quot;Symptom → topic navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Go to</th><th>After reading you can</th></tr></thead><tbody><tr><td>Cannot say why the first token is slow or the bill is rising</td><td><a href="./inference-fundamentals.html">Inference Fundamentals</a></td><td>Decompose one latency into queue / prefill / decode / network and attribute it</td></tr><tr><td>Cannot read why cached input has one price and regular input another</td><td><a href="./efficient-serving.html">Efficient Serving</a></td><td>Map quantization and prefix caching onto billing fields; restructure prompts and sessions</td></tr><tr><td>First request not sent yet / falls over on 429</td><td><a href="./model-api.html">Model API Contract</a></td><td>Write a calling loop with error-family classification and retries</td></tr><tr><td>Answers are stable but cannot enter a program (parsing by regex)</td><td><a href="./structured-output.html">Structured Output</a></td><td>Constrain and validate model output with a schema</td></tr><tr><td>Endpoint works, but UI waits for the full answer</td><td><a href="./streaming.html">Streaming</a></td><td>Consume an SSE stream; cancel and recover from interruption</td></tr><tr><td>Want components in answers, not just text</td><td><a href="./ui.html">Generative UI</a></td><td>Render model output through a component whitelist</td></tr><tr><td>Need lower latency / privacy / offline</td><td><a href="./browser-edge.html">Browser and Edge Inference</a></td><td>Pick the right on-device runtime and fallback chain</td></tr></tbody></table><h3 id="decision-table-interface-side-access-modes" tabindex="-1">Decision table: interface-side access modes <a class="header-anchor" href="#decision-table-interface-side-access-modes" aria-label="Permalink to &quot;Decision table: interface-side access modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Direction</th><th>Control</th><th>State</th><th>Trust domain</th><th>Minimum complexity</th></tr></thead><tbody><tr><td>Direct fetch to a vendor API</td><td>Outbound request/response</td><td>Fully self-managed</td><td>None (rebuilt per turn)</td><td>Keys server-side</td><td>One runnable file</td></tr><tr><td>Official SDK</td><td>Outbound request/response</td><td>SDK handles retries and types</td><td>None</td><td>Keys server-side</td><td>+1 dependency</td></tr><tr><td>Frontend AI framework</td><td>Request + stream + UI bundled</td><td>Framework takes over</td><td>Framework session model</td><td>Keys server-side</td><td>A framework contract</td></tr><tr><td>On-device inference</td><td>Runs in the device</td><td>Fully self-managed</td><td>Device-local</td><td>Data never leaves</td><td>Model distribution + runtime</td></tr></tbody></table><p>The serving-side mode decision (API / self-hosted / on-device) is in the decision table of <a href="./inference-fundamentals.html">Inference Fundamentals</a>. The selection principle is the same: <strong>start at minimum complexity</strong>, add layers only when blocked.</p><h3 id="historical-milestones" tabindex="-1">Historical milestones <a class="header-anchor" href="#historical-milestones" aria-label="Permalink to &quot;Historical milestones&quot;">​</a></h3><p>Vendor API shapes keep evolving (e.g. OpenAI from Chat Completions to the Responses API, Anthropic sampling parameters shrinking across model generations, both vendors shipping prefix caching). This group maintains no vendor timeline; specific fields defer to the official docs at the time of reading, and decision-relevant claims in this repo carry retrievedAt stamps. This page was rewritten in 2026-09 from the v5 &quot;application integration&quot; layer guide into the v6 &quot;Inference &amp; Interface&quot; group guide as part of Issue #116.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>The group&#39;s minimal hands-on is the zero-key two-stage simulator in <a href="./inference-fundamentals.html">Inference Fundamentals</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save that page&#39;s full example as inference-sim.mts, then:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inference-sim.mts</span></span></code></pre></div><p>Acceptance: three output sections — the cost structure with KV cache, the no-cache negative case (identical TTFT, decode amplified 12×), and the savings percentage. Once it runs you have personally verified the attribution rule &quot;prompt hits TTFT, output hits total duration&quot;.</p><p>The cost-side counterpart is the prefix cache calculator in <a href="./efficient-serving.html">Efficient Serving</a> (hit / miss / below-minimum-length scenarios). Every topic&#39;s usage section in this group follows the same constraints: zero API keys, single self-contained file, deterministic output, and positive/negative paths in pairs.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>On the capability-transformation chain, this group turns &quot;one replaceable external capability&quot; into &quot;one operable interaction chain&quot;:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User action → request assembly (structured-output schema + session state)</span></span>
<span class="line"><span>           → serving (inference fundamentals: queue/prefill/decode; efficient serving: caching and quantization)</span></span>
<span class="line"><span>           → API call (model-api: error families, retries, usage)</span></span>
<span class="line"><span>           → streaming presentation (SSE, accumulation, cancellation)</span></span>
<span class="line"><span>           → structured rendering (ui: whitelisted components)</span></span></code></pre></div><ul><li><strong>Invariant 1</strong>: the model API is stateless. Every request resends all needed history; &quot;conversational memory&quot; is an integration-layer construct (→ <a href="./../03-context/session-memory.html">Session and State</a>).</li><li><strong>Invariant 2</strong>: model output is untrusted input. It must pass a schema and a whitelist before rendering.</li><li><strong>Invariant 3</strong>: interactions must be cancellable and observable. Cancellation depends on AbortController reaching the server to stop generation; observation depends on usage (including cache-hit fields) reaching the cost dashboard.</li><li><strong>Invariant 4</strong>: latency and cost are attributable. TTFT, ITL, input/output tokens, and cache hits are instrumented separately — what cannot be decomposed cannot be optimized.</li></ul><p><strong>Exit criteria</strong>: you can deliver a user-visible interaction that is attributable (latency decomposes into segments), observable (usage and hit rates are visible), and cancellable (stops mid-flight with consistent state afterwards).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>Before entering the interface side, use three diagnostics to locate the page you need.</p><h3 id="symptom-→-evidence-→-action-→-done-when" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: users report &quot;forever until the first token&quot;, then it flows. <strong>Evidence</strong>: streaming metrics split TTFT from ITL; prompt token distribution and cache-hit fields. <strong>Action</strong>: work the TTFT runbook in <a href="./inference-fundamentals.html">Inference Fundamentals</a> across queue / prefill / cache invalidation. <strong>Done when</strong>: TTFT p50/p95 return to baseline and you can name the slow segment from the data.</p><h3 id="symptom-→-evidence-→-action-→-done-when-1" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the bill spikes while traffic is flat. <strong>Evidence</strong>: per-turn input tokens inflate linearly with turns; hit rates fall. <strong>Action</strong>: fix cache-friendly structure and history trimming per <a href="./efficient-serving.html">Efficient Serving</a> and <a href="./../03-context/session-memory.html">Session and State</a>. <strong>Done when</strong>: the per-session cost slope falls and hit rates return to baseline.</p><h3 id="symptom-→-evidence-→-action-→-done-when-2" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the demo works perfectly, production fails intermittently. <strong>Evidence</strong>: HTTP status code distribution across failure samples; 429/5xx share. <strong>Action</strong>: add error-family classification and backoff retries per <a href="./model-api.html">Model API Contract</a>; fix quotas before retrying quota errors. <strong>Done when</strong>: under the same traffic, retries converge and no error is left unclassified.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><h3 id="four-level-reading-route" tabindex="-1">Four-level reading route <a class="header-anchor" href="#four-level-reading-route" aria-label="Permalink to &quot;Four-level reading route&quot;">​</a></h3><ul><li><strong>Beginner</strong>: <a href="./inference-fundamentals.html">Inference Fundamentals</a> (run the simulator) → <a href="./model-api.html">Model API Contract</a> (send the first call).</li><li><strong>Builder</strong>: <a href="./efficient-serving.html">Efficient Serving</a> → <a href="./structured-output.html">Structured Output</a> → <a href="./streaming.html">Streaming</a>.</li><li><strong>Operator</strong>: each topic&#39;s development-section runbooks → <a href="./../08-production/observability.html">Observability</a>, <a href="./../08-production/cost-performance.html">Cost and Performance</a>.</li><li><strong>Researcher</strong>: <a href="./ui.html">Generative UI</a> → <a href="./browser-edge.html">Browser and Edge Inference</a> → the papers and engine docs linked from this group&#39;s resource tables (FlashAttention, vLLM).</li></ul><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>The claim &quot;perceived latency is dominated by TTFT&quot; comes from general streaming engineering experience; thresholds for a specific product must be measured.</li><li>The cost units and prices in this group&#39;s two fixtures are teaching constants that verify structure and attribution methods, not any vendor&#39;s real numbers.</li><li>Vendor field names, cache tiers, and error codes change with versions; this group&#39;s tables keep only verified versions and defer to the official docs.</li></ul><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><p>This group answers &quot;how to turn a model into an online service and interface&quot;, not &quot;what the model sees this turn&quot; (→ <a href="./../03-context/session-memory.html">Session and State</a>), &quot;how to bring in knowledge beyond parameters&quot; (→ <a href="./../04-grounding/rag.html">Embeddings and Retrieval</a>), &quot;how to take controlled actions&quot; (→ <a href="./../05-action/tool-calling.html">Tool Calling Contract</a>), or &quot;evidence for launch&quot; (→ <a href="./../08-production/observability.html">Observability</a>).</p>`,34))])}const I=r(u,[["render",p]]);export{x as __pageData,I as default};
